"""Reproducible delivery bundles; only source code and UI catalogs, never business rows."""
from pathlib import Path
import argparse,json,hashlib,re
ROOT=Path(__file__).resolve().parents[2]
BASE=ROOT/'business_insight/cloud_core'
SOURCES=['runtime/mcp-table-read.js','runtime/tablegit.js','source-directory.js','paper-review.js','topic-dossier.js','research-visuals.js','route-evidence.js','monthly-routes.js','industry-updates.js','current-synthesis.js','monthly-corpus.js','compression.js']
def build(topic=False):
    names=[s for s in SOURCES if not(topic and s in ['monthly-routes.js','paper-review.js'])]
    packs={lang:json.loads((BASE/f'data/focus-ui.{lang}.json').read_text()) for lang in ['zh','en']}
    body=['// Generated by tools/cloud_core/build_reader_entry.py. Edit source modules, then rebuild.','globalThis.LRICloudUIPacks='+json.dumps(packs,ensure_ascii=False,separators=(',',':'))+';']
    for name in names:
        text=(BASE/name).read_text().rstrip()
        body.extend(['// Source: '+name,'(()=>{\n'+text+'\n})();' if name=='compression.js' else text])
    return '\n'.join(body)+'\n'
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    for topic,name in [(False,'reader-entry.js'),(True,'topic-entry.js')]:
        expected=build(topic);path=BASE/name
        if args.check:assert path.read_text()==expected,'Reader bundle stale: '+name
        else:path.write_text(expected)
    foundation_packs={lang:json.loads((BASE/f'data/foundations-ui.{lang}.json').read_text()) for lang in ['zh','en']}
    foundation='// Generated shared foundations UI; facts remain in TableGit.\n'+'globalThis.LRICloudFoundationUIPacks='+json.dumps(foundation_packs,ensure_ascii=False,separators=(',',':'))+';\n'+'\n'.join((BASE/name).read_text() for name in ['runtime/mcp-table-read.js','runtime/tablegit.js','foundations.js'])
    foundation_path=BASE/'foundations-entry.js'
    if args.check:assert foundation_path.read_text()==foundation,'Foundation bundle stale'
    else:foundation_path.write_text(foundation)
    bootstrap=(BASE/'reader-bootstrap.js').read_text().rstrip()
    assert '</script' not in bootstrap.lower(),'Bootstrap must remain safe to embed'
    for name in ['index.html','topic.html','monthly.html']:
        path=BASE/name;html=path.read_text()
        pattern=r'<script data-lri-reader-bootstrap>[\s\S]*?</script>'
        expected=re.sub(pattern,lambda _: '<script data-lri-reader-bootstrap>\n'+bootstrap+'\n</script>',html)
        assert len(re.findall(pattern,html))==1,'Missing single first-content bootstrap: '+name
        # An installed worker owns its previous immutable URLs until activation.
        # Content-addressed URLs let ordinary reloads bypass that old worker's cache.
        reader=re.search(r'data-lri-reader="([^"]+)"',expected)[1].split('?')[0]
        reader_hash=hashlib.sha256((BASE/reader).read_bytes()).hexdigest()[:16]
        expected=re.sub(r'data-lri-reader="[^"]+"',lambda _: 'data-lri-reader="'+reader+'?v=reader-content-'+reader_hash+'"',expected)
        if args.check:assert html==expected,'Stale first-content bootstrap or reader URL: '+name
        else:path.write_text(expected)
    config=json.loads((ROOT/'assets/lri-shell.config.json').read_text())
    assets=[('../../assets/insight-executive.css?v='+config['style_version'],ROOT/'assets/insight-executive.css'),('../../assets/lri-shell.js?v='+config['version'],ROOT/'assets/lri-shell.js')]
    for name in ['index.html','topic.html']:
        reader=re.search(r'data-lri-reader="([^"]+)"',(BASE/name).read_text())[1]
        assets.append((reader,BASE/reader.split('?')[0]))
    manifest={url:hashlib.sha256(path.read_bytes()).hexdigest() for url,path in assets}
    digest=hashlib.sha256(json.dumps(manifest,sort_keys=True).encode()).hexdigest()[:16]
    worker='// Generated UI assets only; no HTML, table responses, credentials, or business facts.\nconst CACHE="lri-cloud-ui-'+digest+'";\nconst ASSETS='+json.dumps(manifest,separators=(',',':'))+';\n'+(ROOT/'tools/cloud_core/reader_ui_cache_template.js').read_text()
    path=BASE/'reader-ui-cache.js'
    if args.check:assert path.read_text()==worker,'Reader UI cache stale'
    else:path.write_text(worker)
    print(json.dumps({'pass':True,'generated_bundles':2,'business_records_embedded':False}))
if __name__=='__main__':main()
